-- 194: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_194_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_194_guard;
INSERT INTO _migration_194_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_005' AND NOT (q.topic_id IS 'topic_was_basketry_b004_1' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which material condition should cause a craftsperson to reject a cane intended for a load-bearing rim?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A shallow surface stain that can be cleaned without fibre loss","B. A consistent colour variation that does not interrupt the cane fibres","C. A gradual natural taper that can be allowed for during sizing","D. Deep insect channels that interrupt the fibres"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A load-bearing rim depends on continuous sound fibres, and deep insect damage reduces its section and strength even when the cane can still be bent into the required outline. Therefore the correct answer is D: Deep insect channels that interrupt the fibres.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_005' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_194_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_006' AND NOT (q.topic_id IS 'topic_was_basketry_b004_2' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should guide the selection of cane during responsible harvesting for basketry?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cut stems to one market diameter across each clump and rely on the rootstock for uniform regrowth","B. Choose mature sound stems and leave immature growth to develop","C. Prefer the oldest thick stems even when shallow checks are visible along their length","D. Harvest the softest immature shoots and retain the mature stems for later seasons"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Mature sound stems provide stronger usable fibres, while leaving young growth and regenerative parts supports both future material quality and continued production from the resource. Therefore the correct answer is B: Choose mature sound stems and leave immature growth to develop.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_006' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_194_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_007' AND NOT (q.topic_id IS 'topic_was_basketry_b004_2' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is dry cane soaked or damp-conditioned before it is bent sharply?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Soaking closes insect channels enough to restore a damaged structural length","B. Water raises the natural tensile strength beyond that of sound unsoaked cane","C. Conditioning makes cane water-resistant enough to need no later protection","D. Moisture restores temporary pliability and reduces surface splitting"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Controlled conditioning lets fibres move relative to one another during forming, reducing cracking; it does not repair decay or make an unsuitable bend radius automatically safe. Therefore the correct answer is D: Moisture restores temporary pliability and reduces surface splitting.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_007' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_194_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_008' AND NOT (q.topic_id IS 'topic_was_basketry_b004_2' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main reason for sizing weaving strips to a consistent width and thickness?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Alternate wider and narrower strips by eye while applying the same pull throughout each course","B. Size flexible weavers to the same gauge as the stakes so one dimension serves both structural roles","C. Uniform strips support even tension, spacing and appearance","D. Grade strips to one width but allow thickness to vary so thicker sections reinforce tight bends"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Consistent preparation makes the strips respond similarly during bending and tightening, helping the maker maintain regular courses without local bulges, gaps or weak narrow sections. Therefore the correct answer is C: Uniform strips support even tension, spacing and appearance.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_008' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_005', 'topic_was_basketry_b004_1', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which material condition should cause a craftsperson to reject a cane intended for a load-bearing rim?', 'multiple_choice', NULL, '["A. A shallow surface stain that can be cleaned without fibre loss","B. A consistent colour variation that does not interrupt the cane fibres","C. A gradual natural taper that can be allowed for during sizing","D. Deep insect channels that interrupt the fibres"]', 'D', 'A load-bearing rim depends on continuous sound fibres, and deep insect damage reduces its section and strength even when the cane can still be bent into the required outline. Therefore the correct answer is D: Deep insect channels that interrupt the fibres.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_1', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_006', 'topic_was_basketry_b004_2', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What should guide the selection of cane during responsible harvesting for basketry?', 'multiple_choice', NULL, '["A. Cut stems to one market diameter across each clump and rely on the rootstock for uniform regrowth","B. Choose mature sound stems and leave immature growth to develop","C. Prefer the oldest thick stems even when shallow checks are visible along their length","D. Harvest the softest immature shoots and retain the mature stems for later seasons"]', 'B', 'Mature sound stems provide stronger usable fibres, while leaving young growth and regenerative parts supports both future material quality and continued production from the resource. Therefore the correct answer is B: Choose mature sound stems and leave immature growth to develop.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_2', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_007', 'topic_was_basketry_b004_2', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why is dry cane soaked or damp-conditioned before it is bent sharply?', 'multiple_choice', NULL, '["A. Soaking closes insect channels enough to restore a damaged structural length","B. Water raises the natural tensile strength beyond that of sound unsoaked cane","C. Conditioning makes cane water-resistant enough to need no later protection","D. Moisture restores temporary pliability and reduces surface splitting"]', 'D', 'Controlled conditioning lets fibres move relative to one another during forming, reducing cracking; it does not repair decay or make an unsuitable bend radius automatically safe. Therefore the correct answer is D: Moisture restores temporary pliability and reduces surface splitting.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_2', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_008', 'topic_was_basketry_b004_2', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What is the main reason for sizing weaving strips to a consistent width and thickness?', 'multiple_choice', NULL, '["A. Alternate wider and narrower strips by eye while applying the same pull throughout each course","B. Size flexible weavers to the same gauge as the stakes so one dimension serves both structural roles","C. Uniform strips support even tension, spacing and appearance","D. Grade strips to one width but allow thickness to vary so thicker sections reinforce tight bends"]', 'C', 'Consistent preparation makes the strips respond similarly during bending and tightening, helping the maker maintain regular courses without local bulges, gaps or weak narrow sections. Therefore the correct answer is C: Uniform strips support even tension, spacing and appearance.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_2', 'Identify', 'AO2', NULL, NULL, 'board_waec');
